let mealRestaurants=[],mealUsers=[],mealWeeklyStatus=[],mealWeek='',mealEntries=[];
let mealAvailability=[],mealConfirmations=[];
const mealDayNames=['월','화','수','목','금'];
function registrySampleMarkup(){return panel('가상 등기부등본으로 살펴보기',`<p class="registry-example-note">학습용 가상 문서입니다. 주소·인물·금액은 모두 예시이며 실제 등기사항증명서가 아닙니다.</p><div class="registry-paper"><div class="registry-watermark" aria-hidden="true">학습용 가상 예시</div><h2>등기사항전부증명서 · 학습용 예시</h2><p>[집합건물] 부산광역시 가상구 학습로 100, 예시아파트 101동 301호</p><h3>표제부 — 건물의 표시</h3><div class="registry-table-scroll"><table><thead><tr><th>표시번호</th><th>접수</th><th>소재지번·건물명</th><th>건물내역</th></tr></thead><tbody><tr><td>1</td><td>2020년 3월 2일</td><td>부산광역시 가상구 예시동 100<br>예시아파트 101동</td><td>철근콘크리트구조<br>10층 공동주택</td></tr></tbody></table></div><h3>표제부 — 전유부분의 표시</h3><div class="registry-table-scroll"><table><thead><tr><th>표시번호</th><th>건물번호</th><th>건물내역</th><th>등기원인 및 기타사항</th></tr></thead><tbody><tr><td>1</td><td>제3층 제301호</td><td>철근콘크리트구조<br>84.00㎡</td><td>2020년 3월 2일 등기</td></tr></tbody></table></div><h3>갑구 — 소유권에 관한 사항</h3><div class="registry-table-scroll"><table><thead><tr><th>순위번호</th><th>등기목적</th><th>접수</th><th>등기원인</th><th>권리자 및 기타사항</th></tr></thead><tbody><tr><td>1</td><td>소유권보존</td><td>2020년 3월 2일<br>제100호</td><td>—</td><td>소유자 홍인턴 (가상 인물)<br>식별정보 생략<br>부산광역시 가상구 학습로 100</td></tr></tbody></table></div><h3>을구 — 소유권 이외의 권리에 관한 사항</h3><div class="registry-table-scroll"><table><thead><tr><th>순위번호</th><th>등기목적</th><th>접수</th><th>등기원인</th><th>권리자 및 기타사항</th></tr></thead><tbody><tr><td>1</td><td>근저당권설정</td><td>2021년 4월 5일<br>제200호</td><td>2021년 4월 5일<br>설정계약</td><td>채권최고액 금120,000,000원<br>채무자 홍인턴<br>근저당권자 가상은행</td></tr></tbody></table></div><p class="registry-footer">일부 항목을 생략한 학습용 구성 예시 · 제출 및 증명 용도로 사용할 수 없음</p></div><div class="cards registry-reading"><article><h3>① 표제부</h3><p>소재지, 건물명, 층·호수, 면적 등 부동산의 표시를 살펴보세요.</p></article><article><h3>② 갑구</h3><p>소유권에 관한 등기 내용을 살펴보세요. 이 예시의 소유자는 홍인턴입니다.</p></article><article><h3>③ 을구</h3><p>근저당권 등 소유권 이외의 권리를 살펴보세요. 예시의 채권최고액은 1억 2천만 원입니다.</p></article></div><a class="board-source" href="https://www.easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=2&cciNo=1&cnpClsNo=1&csmSeq=629" target="_blank" rel="noopener noreferrer">생활법령정보: 등기부 구성 안내 ↗</a>`);}
function mealDayInputs(selected=[]){return `<fieldset class="meal-weekdays"><legend>가능한 요일 (여러 날 선택)</legend>${mealDayNames.map((name,i)=>`<label><input type="checkbox" name="days" value="${i}" ${selected.includes(i)?'checked':''}>${name}</label>`).join('')}</fieldset>`;}
function mealAvailabilityMarkup(id){const rows=mealAvailability.filter(x=>x.meal_id===id);return rows.length?`<details class="meal-participant-details"><summary>참여자 가능한 요일 <span>${rows.length}명</span></summary><div class="meal-availability">${rows.map(x=>`<p><span>${esc(x.name)}</span><small>${x.days.length?x.days.map(d=>mealDayNames[d]).join(' · '):'요일 미선택'}</small></p>`).join('')}</div></details>`:'';}
function showMealDays(id,action){let modal=document.querySelector('#meal-days-dialog');if(!modal){modal=document.createElement('dialog');modal.id='meal-days-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>가능한 식사 요일</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="meal-days-form" data-id="${id}" data-action="${action}" class="board-form">${mealDayInputs(mealAvailability.find(x=>x.meal_id===id&&x.user_id===window.hfAuth.user.id)?.days||[])}<button type="submit" class="primary">${action==='availability'?'요일 저장':'요일 선택하고 참여'}</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('.meal-day-edit');if(b)showMealDays(Number(b.dataset.id),'availability');});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='meal-days-form')return;e.preventDefault();const days=new FormData(form).getAll('days').map(Number),button=form.querySelector('[type=submit]');if(!days.length){form.querySelector('.board-status').textContent='가능한 요일을 하나 이상 선택해 주세요.';return;}button.disabled=true;try{await mealRequest('/'+form.dataset.action,{id:Number(form.dataset.id),days,...(form.dataset.action==='respond'?{action:'accept'}:{})});form.closest('dialog').close();await loadMealInvitations();if(document.querySelector('#meal-invitations-dialog')?.open)showMealInvitations();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
document.addEventListener('click',async e=>{const button=e.target.closest('.meal-delete');if(!button)return;if(!confirm('식사 제안을 삭제할까요? 보낸 초대도 함께 삭제됩니다.'))return;button.disabled=true;try{await mealRequest('/remove',{id:Number(button.dataset.id)});await loadMealInvitations();render();}catch(error){button.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;button.after(p);}});
async function renderSharedMeals(content){
 content.innerHTML+=`<div class="meal-compose-bar"><div><h2>함께 식사할 사람을 찾아보세요</h2><p>시간과 식당을 정하고, 가능한 요일을 공유해요.</p></div><button type="button" class="primary" id="meal-create"><span aria-hidden="true">＋</span> 식사 제안하기</button></div><p class="meal-reward-guide">함께 식사하면 하루 10 XP · 처음 함께 먹는 회원마다 추가 5 XP<br><small>참여자 2명 이상이 완료를 확인하면 반영됩니다. 첫 확인 이후에는 참여자를 변경할 수 없습니다.</small></p><section class="meal-proposals" aria-labelledby="meal-proposals-title"><div class="meal-list-heading"><h2 id="meal-proposals-title">제안된 식사</h2><span id="meal-count" class="meal-count"></span></div><div id="meal-list" class="meal-proposal-grid" aria-live="polite">식사 제안을 불러오는 중…</div></section>`;
 try{const data=await mealRequest();if(!content.isConnected)return;mealWeek=data.week;mealEntries=data.meals;mealWeeklyStatus=data.weekly_status||[];mealRestaurants=data.restaurants;mealUsers=data.users;mealAvailability=data.availability||[];mealConfirmations=data.confirmations||[];content.querySelector('#meal-count').textContent=data.meals.length+'개';content.querySelector('#meal-list').innerHTML=data.meals.length?data.meals.map(m=>{const own=m.user_id===window.hfAuth.user.id,joined=m.members.includes(window.hfAuth.user.id),full=m.members.length>=m.capacity,confirmed=mealConfirmations.filter(c=>c.meal_id===m.id),didConfirm=confirmed.some(c=>c.user_id===window.hfAuth.user.id),closed=confirmed.length>0;return `<article class="meal-card meal-card-clean"><header class="meal-card-heading"><h3>${esc(m.restaurant)}</h3><span class="meal-card-status">${closed?'완료 확인 중':full?'모집 마감':'모집 중'}</span></header><div class="meal-card-meta"><p class="meal-card-time">${esc(m.event_time.replace('T',' · '))}</p><p class="meal-card-host">${esc(m.author)}님의 제안 <span>·</span> ${m.members.length} / ${m.capacity}명</p>${m.address?`<p class="meal-card-address">${esc(m.address)}</p>`:''}${m.url?`<a class="meal-map-link" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">지도에서 위치 보기 ↗</a>`:''}</div>${mealAvailabilityMarkup(m.id)}<div class="meal-card-main-actions">${own?`<button type="button" class="primary meal-invite-open" data-id="${m.id}" ${closed||full?'disabled':''}>회원 초대하기</button>`:`<button type="button" class="${joined?'auth-link':'primary'} meal-join" data-id="${m.id}" ${closed||full&&!joined?'disabled':''}>${joined?'참여 취소':full?'정원 마감':'참여하기'}</button>`}${joined?`<button type="button" class="auth-link meal-day-edit" data-id="${m.id}">가능 요일 수정</button>`:''}</div>${joined||confirmed.length?`<div class="meal-card-complete"><span>${confirmed.length?`완료 확인 ${confirmed.length} / ${m.members.length}명`:'식사 후 완료를 확인해 주세요'}</span>${joined?`<button type="button" class="meal-complete auth-link" data-id="${m.id}" ${didConfirm?'disabled':''}>${didConfirm?'✓ 확인 완료':'식사 완료 확인'}</button>`:''}</div>`:''}${own?`<footer class="meal-card-owner"><span>내가 만든 제안</span><button type="button" class="task-delete meal-delete" data-id="${m.id}">제안 삭제</button></footer>`:''}</article>`;}).join(''):'<div class="meal-empty"><strong>첫 식사를 제안해 보세요</strong><p>등록된 제안이 여기에 표시됩니다.</p></div>';}catch(error){content.querySelector('#meal-list').textContent=error.message;}
}
async function showMealInviteForm(id){let modal=document.querySelector('#meal-invite-dialog');if(!modal){modal=document.createElement('dialog');modal.id='meal-invite-dialog';document.body.append(modal);}const meal=mealEntries.find(m=>m.id===id),targetWeek=mealWeekOf(meal?.event_time.slice(0,10)||mealCurrentTime().day);let statusRows=[];try{const data=await mealRequest('/weekly?week='+targetWeek);statusRows=data.weekly_status;}catch(error){alert(error.message);return;}const users=mealUsers.filter(u=>u.id!==window.hfAuth.user.id&&!meal?.members.includes(u.id));modal.innerHTML=`<div class="progress-dialog-head"><h2>함께 식사할 회원 초대</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="meal-invite-form" data-id="${id}" class="board-form"><p class="muted">초대받은 회원이 수락하면 참여 인원에 포함됩니다.</p><p class="muted">${esc(targetWeek)} 시작 주 · 가능 / 불가 / 미설정 상태를 확인하고 초대하세요.</p><div class="meal-member-list">${users.length?users.map(u=>`<label class="meal-member"><input type="checkbox" name="recipients" value="${u.id}"><span>${esc(u.name)}${u.department?`<small>${esc(u.department)}</small>`:''}${mealInviteStatus(statusRows.find(r=>r.user_id===u.id))}</span></label>`).join(''):'<p>초대할 승인된 회원이 없습니다.</p>'}</div><button type="submit" class="primary" ${users.length?'':'disabled'}>선택한 회원에게 초대 보내기</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('.meal-invite-open');if(b)showMealInviteForm(Number(b.dataset.id));});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='meal-invite-form')return;e.preventDefault();const recipients=new FormData(form).getAll('recipients').map(Number),button=form.querySelector('[type=submit]'),status=form.querySelector('.board-status');if(!recipients.length){status.textContent='초대할 회원을 선택해 주세요.';return;}button.disabled=true;try{await mealRequest('/invite',{id:Number(form.dataset.id),recipients});status.textContent='초대를 보냈습니다. 회원들이 사이트에 접속하면 알림을 받습니다.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
let mealInvitations=[],mealInviteLoading=false;const mealInviteShown=new Set();
async function loadMealInvitations(){if(mealInviteLoading||!window.hfAuth||document.hidden)return;mealInviteLoading=true;try{const data=await mealRequest('/invitations');mealInvitations=data.invitations;let button=document.querySelector('#meal-invitation-button');if(!button){button=document.createElement('button');button.id='meal-invitation-button';button.className='auth-link';button.type='button';button.onclick=()=>showMealInvitations();document.querySelector('.auth-tools')?.append(button);}button.textContent=`식사 초대 ${mealInvitations.length}개`;button.hidden=!mealInvitations.length;if(mealInvitations.some(i=>!mealInviteShown.has(i.id))&&!document.querySelector('dialog[open]'))showMealInvitations();}catch{}finally{mealInviteLoading=false;}}
function showMealInvitations(){let modal=document.querySelector('#meal-invitations-dialog');if(!modal){modal=document.createElement('dialog');modal.id='meal-invitations-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>받은 식사 초대</h2><button type="button" class="auth-link" data-close>닫기</button></div>`+(mealInvitations.length?mealInvitations.map(i=>{mealInviteShown.add(i.id);return `<article class="meal-card"><h3>${esc(i.author)}님이 식사에 초대했어요</h3><p>${esc(i.restaurant)} · ${esc(i.event_time.replace('T',' '))}</p><p>${i.members.length} / ${i.capacity}명 참여</p><div class="meal-card-actions"><button type="button" class="primary meal-invite-respond" data-id="${i.id}" data-action="accept">수락하고 참여</button><button type="button" class="auth-link meal-invite-respond" data-id="${i.id}" data-action="decline">거절</button></div><p class="board-status" role="status"></p></article>`;}).join(''):'<p>응답할 초대가 없습니다.</p>');modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
document.addEventListener('click',async e=>{const button=e.target.closest('.meal-invite-respond');if(!button)return;if(button.dataset.action==='accept'){showMealDays(Number(button.dataset.id),'respond');return;}const card=button.closest('article');card.querySelectorAll('button').forEach(b=>b.disabled=true);try{await mealRequest('/respond',{id:Number(button.dataset.id),action:button.dataset.action});await loadMealInvitations();showMealInvitations();if(location.hash==='#lunch')render();}catch(error){card.querySelector('.board-status').textContent=error.message;card.querySelectorAll('button').forEach(b=>b.disabled=false);}});
setInterval(loadMealInvitations,15000);
async function wikiRequest(path='',data){const r=await fetch('/api/wiki'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'문서를 처리하지 못했습니다.');return result;}
let wikiUploadImages=[],wikiUploadVersion=0;
function showWikiForm(){wikiUploadImages=[];wikiUploadVersion++;const user=window.hfAuth.user;let modal=document.querySelector('#wiki-compose-dialog');if(!modal){modal=document.createElement('dialog');modal.id='wiki-compose-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>문서 등록</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="wiki-document-form" class="board-form"><div class="meal-datetime"><label>작성자<input class="field" value="${esc(user.name)}" readonly aria-readonly="true"></label><label>부서<select class="field" name="department" required>${wikiDepartments.map(d=>`<option value="${esc(d)}" ${d===wikiDepartment?'selected':''}>${esc(d)}</option>`).join('')}</select></label></div><label>문서 제목<input class="field" name="title" maxlength="120" required placeholder="문서 제목을 입력하세요"></label><label>내용<textarea class="field" name="body" maxlength="5000" rows="8" required placeholder="업무 인수인계나 인턴 생활 팁을 남겨 주세요"></textarea></label><label>사진 첨부<input class="field" id="wiki-photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="muted">JPG·PNG·WebP, 최대 3장 · 사진당 원본 10MB 이하. 업로드할 때 크기를 자동으로 줄입니다.</p><div id="wiki-photo-preview" class="wiki-photo-preview"></div><button type="submit" class="primary">문서 등록</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}
document.addEventListener('click',e=>{if(e.target.closest('#wiki-create'))showWikiForm();});
let wikiDepartments=['유동화자산처'],wikiDepartment='',wikiSearch='',wikiPage=1,wikiLoadVersion=0;
async function renderWiki(content){content.innerHTML+=`<div class="meal-compose-bar"><div><h2>인턴들의 업무 노트</h2><p>부서를 선택하고 제목으로 필요한 문서를 찾아보세요.</p></div><button type="button" id="wiki-create" class="primary">＋ 문서 등록</button></div><nav id="wiki-departments" class="wiki-departments" aria-label="위키 부서 분류"></nav><form id="wiki-search-form" class="wiki-search"><input class="field" name="q" maxlength="120" value="${esc(wikiSearch)}" aria-label="위키 제목 검색" placeholder="문서 제목 검색"><button class="primary">검색</button></form><section aria-labelledby="wiki-documents-title"><div class="meal-list-heading"><h2 id="wiki-documents-title">등록된 문서</h2><span id="wiki-count" class="meal-count"></span></div><div id="wiki-document-list" class="wiki-title-list" aria-live="polite"></div><div id="wiki-pagination" class="wiki-pagination"></div></section>`;await loadWikiList();}
async function loadWikiList(){const list=document.querySelector('#wiki-document-list');if(!list)return;const version=++wikiLoadVersion;list.textContent='문서를 불러오는 중…';try{const query=new URLSearchParams({department:wikiDepartment,q:wikiSearch,page:wikiPage});const data=await wikiRequest('?'+query);if(!list.isConnected||version!==wikiLoadVersion)return;wikiDepartments=data.departments;wikiPage=data.page;document.querySelector('#wiki-departments').innerHTML=[['','전체',data.groups.reduce((sum,r)=>sum+r.count,0)],...wikiDepartments.map(d=>[d,d,data.groups.find(r=>r.department===d)?.count||0])].map(([value,label,count])=>`<button type="button" data-wiki-department="${esc(value)}" aria-pressed="${value===wikiDepartment}" class="${value===wikiDepartment?'selected':''}">${esc(label)} <small>${count}</small></button>`).join('');document.querySelector('#wiki-documents-title').textContent=wikiDepartment?wikiDepartment+' 문서':'전체 문서';document.querySelector('#wiki-count').textContent=data.total+'개';list.innerHTML=data.documents.length?data.documents.map(d=>`<button type="button" class="wiki-title-row" data-wiki-open="${d.id}"><span class="wiki-title-main"><strong>${esc(d.title)}</strong></span><time>${esc(d.created.slice(0,10))}</time><span aria-hidden="true">›</span></button>`).join(''):'<div class="meal-empty"><strong>표시할 문서가 없습니다</strong><p>다른 부서나 검색어를 선택하거나 첫 문서를 등록해 주세요.</p></div>';document.querySelector('#wiki-pagination').innerHTML=`<button type="button" class="auth-link" data-wiki-page="${data.page-1}" ${data.page===1?'disabled':''}>이전</button><span>${data.page} / ${data.pages} 페이지</span><button type="button" class="auth-link" data-wiki-page="${data.page+1}" ${data.page===data.pages?'disabled':''}>다음</button>`;}catch(error){if(list.isConnected)list.textContent=error.message;}}
async function showWikiDocument(id){let modal=document.querySelector('#wiki-read-dialog');if(!modal){modal=document.createElement('dialog');modal.id='wiki-read-dialog';document.body.append(modal);}modal.innerHTML='<div class="progress-dialog-head"><h2>문서 보기</h2><button type="button" class="auth-link" data-close>닫기</button></div><div id="wiki-read-body">문서를 불러오는 중…</div>';modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();try{const data=await wikiRequest('/document?id='+id),d=data.document,user=window.hfAuth.user;if(!modal.open)return;modal.querySelector('h2').textContent=d.title;modal.querySelector('#wiki-read-body').innerHTML=`<p class="muted">${esc(d.department)} · ${esc(d.author)} · ${esc(d.created.slice(0,10))}</p><p class="board-body">${esc(d.body)}</p><div class="wiki-document-images">${(d.images||[]).map(i=>`<figure><a href="${esc(i.url)}" target="_blank" rel="noopener"><img src="${esc(i.url)}" alt="${esc(i.name)}" loading="lazy"></a><figcaption>${esc(i.name)}</figcaption></figure>`).join('')}</div>${d.user_id===user.id||user.role==='admin'?`<button type="button" class="task-delete wiki-delete" data-id="${d.id}">문서 삭제</button>`:''}`;}catch(error){modal.querySelector('#wiki-read-body').textContent=error.message;}}
document.addEventListener('submit',e=>{if(e.target.id!=='wiki-search-form')return;e.preventDefault();wikiSearch=new FormData(e.target).get('q').trim();wikiPage=1;loadWikiList();});
document.addEventListener('click',e=>{const department=e.target.closest('[data-wiki-department]'),page=e.target.closest('[data-wiki-page]'),doc=e.target.closest('[data-wiki-open]');if(department){wikiDepartment=department.dataset.wikiDepartment;wikiPage=1;loadWikiList();}else if(page){wikiPage=Number(page.dataset.wikiPage);loadWikiList();}else if(doc)showWikiDocument(Number(doc.dataset.wikiOpen));});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='wiki-document-form')return;e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{const fields=Object.fromEntries(new FormData(form));await wikiRequest('/post',{...fields,images:wikiUploadImages.map(i=>({name:i.name,data:i.data.split(',')[1]}))});form.closest('dialog').close();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
document.addEventListener('click',async e=>{const button=e.target.closest('.wiki-delete');if(!button)return;if(!confirm('이 문서를 삭제할까요?'))return;button.disabled=true;try{await wikiRequest('/remove',{id:Number(button.dataset.id)});button.closest('dialog')?.close();render();}catch(error){button.disabled=false;const message=document.createElement('p');message.setAttribute('role','alert');message.textContent=error.message;button.after(message);}});
function mealCurrentTime(date=new Date()){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return {day:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`};}
document.addEventListener('click',async e=>{const button=e.target.closest('#meal-map-search');if(!button)return;const form=button.closest('form'),results=form.querySelector('#meal-map-results'),query=form.querySelector('[name=restaurant]').value.trim();if(!query){results.textContent='지역과 식당 이름을 입력해 주세요. 예: 문현동 한식';return;}button.disabled=true;results.textContent='카카오 지도에서 검색 중…';try{const data=await mealRequest('/restaurants?q='+encodeURIComponent(query));if(!form.isConnected)return;results.innerHTML=data.places.length?data.places.map((p,i)=>`<button type="button" class="place-result" data-place-index="${i}"><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></button>`).join(''):'검색 결과가 없습니다. 지역 이름을 함께 입력해 보세요.';results.querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=data.places[Number(b.dataset.placeIndex)];form.querySelector('[name=restaurant]').value=p.name;form.querySelector('[name=address]').value=p.address;form.querySelector('[name=url]').value=p.url;form.querySelector('#meal-restaurant-tag').innerHTML=`<span class="restaurant-tag">${esc(p.name)}</span><p class="muted">${esc(p.address)}</p>`;results.innerHTML='';});}catch(error){results.textContent=error.message;}finally{button.disabled=false;}});
async function mealRequest(path='',data){const r=await fetch('/api/meals'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'요청에 실패했습니다.');return result;}
async function renderMeals(content){await renderSharedMeals(content);}
function showMealForm(){const now=mealCurrentTime();let modal=document.querySelector('#meal-dialog');if(!modal){modal=document.createElement('dialog');modal.id='meal-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>식사 제안하기</h2><button type="button" class="auth-link" data-meal-close>닫기</button></div><form id="meal-proposal-form" class="board-form"><div class="meal-datetime"><label>날짜<input class="field" name="meal_day" type="date" value="${now.day}" required></label><label>시간<input class="field" name="meal_time" type="time" value="${now.time}" step="60" required></label></div><label>식당 검색<input class="field" name="restaurant" id="meal-restaurant" list="meal-restaurants" maxlength="120" required placeholder="식당 이름을 검색하거나 새로 입력하세요"><datalist id="meal-restaurants">${mealRestaurants.map(r=>`<option value="${esc(r)}"></option>`).join('')}</datalist></label><button type="button" class="primary" id="meal-map-search">지도에서 식당 검색</button><div id="meal-map-results" aria-live="polite"></div><input type="hidden" name="address"><input type="hidden" name="url"><div id="meal-restaurant-tag"></div><p class="muted">회원들이 등록한 식당을 검색합니다. 새 이름을 입력하면 등록할 수 있습니다.</p>${mealDayInputs()}<label>정원 (본인 포함)<input class="field" name="capacity" type="number" min="2" max="30" value="4" required></label><button type="submit" class="primary">식사 제안 등록</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-meal-close]').onclick=()=>modal.close();modal.querySelector('#meal-restaurant').oninput=e=>{modal.querySelector('[name=address]').value='';modal.querySelector('[name=url]').value='';modal.querySelector('#meal-restaurant-tag').innerHTML=e.target.value.trim()?`<span class="restaurant-tag">${esc(e.target.value.trim())}</span>`:'';};modal.showModal();}
document.addEventListener('click',async e=>{if(e.target.closest('#meal-create')){showMealForm();return;}const b=e.target.closest('.meal-join');if(!b)return;if(b.textContent==='참여하기'){showMealDays(Number(b.dataset.id),'join');return;}b.disabled=true;try{await mealRequest('/join',{id:Number(b.dataset.id)});render();}catch(error){b.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;b.after(p);}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='meal-proposal-form')return;e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form)),days=new FormData(form).getAll('days').map(Number);if(!days.length)throw Error('가능한 요일을 하나 이상 선택해 주세요.');await mealRequest('/post',{...data,days,event_time:data.meal_day+'T'+data.meal_time,capacity:Number(data.capacity)});form.closest('dialog').close();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
async function boardRequest(path,data){
 const response=await fetch('/api/boards/'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});
 const result=await response.json();if(!response.ok)throw Error(result.error||'요청에 실패했습니다.');if(data)loadActivity();return result;
}
async function renderBoard(kind,content){
 if(kind==='articles'){content.innerHTML+=`<section class="auto-news-section"><div class="meal-list-heading"><h2>자동으로 모은 최신 기사</h2><span class="meal-count">경제·금융 / 부동산</span></div><p class="muted">매일경제 RSS · 제목을 누르면 기사 원문으로 이동합니다.</p><div id="auto-news-filters" class="wiki-departments"></div><p id="auto-news-status" class="muted" role="status"></p><div id="auto-news-list" class="wiki-title-list">기사를 불러오는 중…</div></section>`;loadAutoNews();return;}
 const admin=window.hfAuth.user.role==='admin',news=['articles','jobs'].includes(kind);
 const intro={study:'공부할 주제와 시간, 장소를 적고 함께할 인턴을 찾아보세요.',articles:'관리자가 직접 추천한 기사와 원문 링크도 함께 모아 봅니다.',jobs:'관리자가 등록한 채용 공고입니다. 지원 조건과 마감일은 원문에서 확인하세요.',qna:admin?'인턴들의 비공개 질문에 답변해 주세요.':'질문은 작성자와 관리자만 볼 수 있습니다.',suggestions:'포털 개선 아이디어와 인턴 생활에 대한 의견을 함께 나눠요.'}[kind];
 content.innerHTML+=panel(titles[kind],`<p>${intro}</p><p class="muted">${calendarToday} · ${kind==='articles'?'관리자 추천 기사':news?'직접 등록한 소식 · 자동 수집은 아직 연결되지 않았습니다.':'승인된 인턴들이 사용하는 게시판입니다.'}</p>`);
 if(!news||admin)content.innerHTML+=panel(news?'소식 등록':kind==='study'?'공부 모임 만들기':kind==='qna'?'질문하기':'건의사항 작성',`<form id="board-form" data-kind="${kind}" class="board-form"><label>제목<input class="field" name="title" maxlength="120" required placeholder="${kind==='study'?'예: 퇴근 후 NCS 같이 공부해요':'제목을 입력하세요'}"></label>${kind==='study'?'<label>모임 날짜<input type="date" class="field" name="event_day" required></label>':''}<label>${kind==='study'?'공부 주제 · 시간 · 장소':'내용'}<textarea class="field" name="body" maxlength="5000" required rows="4" placeholder="내용을 입력하세요"></textarea></label>${news?'<label>원문 주소<input type="url" class="field" name="link" required placeholder="https://..."></label>':''}<button class="primary">${news?'소식 등록':'등록하기'}</button><p class="board-status" role="status"></p></form>`);
 const list=document.createElement('div');list.className='board-list';list.innerHTML='<p role="status">게시글을 불러오는 중…</p>';content.append(list);

 try{const {posts}=await boardRequest(kind);if(!content.isConnected)return;
 list.innerHTML=posts.length?posts.map(p=>{
  const today=p.created.slice(0,10)===calendarToday;const own=p.user_id===window.hfAuth.user.id;const joined=p.members.includes(window.hfAuth.user.id);
  const answered=p.replies.some(r=>r.admin);
  return panel(`${esc(p.title)} ${today?'<small class="board-tag">오늘</small>':''}`,`<p class="muted">${esc(p.author)} · ${esc(p.created.slice(0,10))}${kind==='qna'?' · '+(answered?'답변 완료':'답변 대기'):''}</p>${kind==='study'?`<p class="board-meta">모임 날짜 ${esc(p.event_day)} · ${p.members.length}명 참여</p>`:''}<p class="board-body">${esc(p.body)}</p>${p.link?`<a class="board-source" href="${esc(p.link)}" target="_blank" rel="noopener noreferrer">${kind==='jobs'?'채용 공고 원문 보기':'기사 원문 보기'} ↗</a>`:''}${kind==='study'?`<button type="button" class="primary board-join" data-id="${p.id}" ${own?'disabled':''}>${own?'내가 만든 모임':joined?'참여 취소':'함께 공부하기'}</button>`:''}${p.replies.map(r=>`<div class="board-reply"><strong>${esc(r.name)}${r.admin?' · 관리자':''}</strong><small> ${esc(r.created.slice(0,10))}</small><p class="board-body">${esc(r.body)}</p></div>`).join('')}<form class="board-reply-form toolbar" data-id="${p.id}"><input name="body" class="field" aria-label="${kind==='qna'?'답변 또는 추가 질문':'댓글'}" placeholder="${kind==='qna'?'답변 또는 추가 질문을 입력하세요':'댓글을 입력하세요'}" maxlength="2000" required><button class="primary">${kind==='qna'?'답변 등록':'댓글 등록'}</button><p class="board-status" role="status"></p></form>`);
 }).join(''):panel('아직 등록된 글이 없어요',`<p>${news?'관리자가 소식을 등록하면 이곳에 표시됩니다.':'첫 글을 남겨 주세요.'}</p>`);
 }catch(e){list.innerHTML=panel('불러오지 못했어요',`<p role="alert">${esc(e.message)}</p><button type="button" class="primary" id="board-retry">다시 시도</button>`);list.querySelector('button').onclick=()=>render();}
}
document.addEventListener('submit',async e=>{
 const form=e.target;if(form.id!=='board-form'&&!form.classList.contains('board-reply-form'))return;
 e.preventDefault();const button=form.querySelector('button'),status=form.querySelector('.board-status');button.disabled=true;status.textContent='저장 중…';
 try{const data=Object.fromEntries(new FormData(form));if(form.id==='board-form')await boardRequest('post',{...data,kind:form.dataset.kind});else await boardRequest('reply',{id:Number(form.dataset.id),body:data.body});render();}
 catch(error){status.textContent=error.message;button.disabled=false;}
});
document.addEventListener('click',async e=>{
 const button=e.target.closest('.board-join');if(!button)return;button.disabled=true;
 try{await boardRequest('join',{id:Number(button.dataset.id)});render();}catch(error){button.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;button.after(p);}
});

document.addEventListener('click',async e=>{const b=e.target.closest('.meal-complete');if(!b)return;b.disabled=true;try{const result=await mealRequest('/complete',{id:Number(b.dataset.id)});await loadActivity();await render();const notice=document.createElement('p');notice.className='meal-reward-guide';notice.setAttribute('role','status');notice.textContent=result.confirmed<2?'완료를 확인했습니다. 다른 참여자의 확인 후 경험치가 반영됩니다.':result.earned?`식사 완료! ${result.earned} XP를 받았습니다.`:'완료를 확인했습니다. 중복 보상은 지급되지 않습니다.';document.querySelector('.meal-compose-bar')?.after(notice);}catch(error){b.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;b.after(p);}});

function mealWeekOf(day){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
function mealWeeklyChips(statuses=[-1,-1,-1,-1,-1]){return '<span class="meal-status-chips">'+mealDayNames.map((name,i)=>`<span class="meal-status-chip ${statuses[i]===1?'available':statuses[i]===0?'unavailable':'unknown'}">${name} ${statuses[i]===1?'가능':statuses[i]===0?'불가':'미설정'}</span>`).join('')+'</span>';}

function mealInviteStatus(row){return '<span class="meal-invite-status"><small>점심</small>'+mealWeeklyChips(row?.lunch)+'<small>저녁</small>'+mealWeeklyChips(row?.dinner)+'</span>';}
function mealStatusSelect(kind,i,value){return `<select class="field" name="${kind}${i}" aria-label="${mealDayNames[i]}요일 ${kind==='lunch'?'점심':'저녁'} 가능 여부"><option value="-1" ${value===-1?'selected':''}>미설정</option><option value="1" ${value===1?'selected':''}>가능</option><option value="0" ${value===0?'selected':''}>불가능</option></select>`;}
function mealWeeklyForm(){const status=mealWeeklyStatus.find(r=>r.user_id===window.hfAuth.user.id),lunch=status?.lunch||[-1,-1,-1,-1,-1],dinner=status?.dinner||[-1,-1,-1,-1,-1];return `<p class="muted">${esc(mealWeek)} 시작 주 · 초대 화면에 공유됩니다.</p><form id="meal-weekly-form" data-week="${esc(mealWeek)}"><div class="meal-profile-grid"><span></span><strong>점심</strong><strong>저녁</strong>${mealDayNames.map((name,i)=>`<strong>${name}요일</strong>${mealStatusSelect('lunch',i,lunch[i])}${mealStatusSelect('dinner',i,dinner[i])}`).join('')}</div><p class="muted meal-profile-note">매주 새로 설정해 주세요. 이전 주 상태는 다음 주로 복사되지 않습니다.</p><button type="submit" class="primary">내 상태 저장</button><p class="board-status" role="status"></p></form>`;}
async function showMealProfile(){let modal=document.querySelector('#meal-profile-dialog');if(!modal){modal=document.createElement('dialog');modal.id='meal-profile-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>${esc(window.hfAuth.user.name)}님의 식사 상태</h2><button type="button" class="auth-link" data-close>닫기</button></div><div id="meal-profile-body" aria-live="polite">이번 주 상태를 불러오는 중…</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();try{const data=await mealRequest('/weekly');mealWeek=data.week;mealWeeklyStatus=data.weekly_status;modal.querySelector('#meal-profile-body').innerHTML=mealWeeklyForm();}catch(error){modal.querySelector('#meal-profile-body').textContent=error.message;}}
document.addEventListener('click',e=>{if(e.target.closest('.meal-profile-open'))showMealProfile();});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='meal-weekly-form')return;e.preventDefault();const b=f.querySelector('button'),d=new FormData(f);b.disabled=true;try{await mealRequest('/weekly',{week:f.dataset.week,lunch:mealDayNames.map((_,i)=>Number(d.get('lunch'+i))),dinner:mealDayNames.map((_,i)=>Number(d.get('dinner'+i)))});const data=await mealRequest('/weekly');mealWeeklyStatus=data.weekly_status;f.querySelector('.board-status').textContent='이번 주 점심·저녁 상태를 저장했습니다.';}catch(error){f.querySelector('.board-status').textContent=error.message;}finally{b.disabled=false;}});

function wikiPhotoPreview(){const box=document.querySelector('#wiki-photo-preview');if(box)box.innerHTML=wikiUploadImages.map((i,index)=>`<div><img src="${i.data}" alt="${esc(i.name)}"><span>${esc(i.name)}</span><button type="button" class="auth-link" data-wiki-photo-remove="${index}">첨부 취소</button></div>`).join('');}
async function compressWikiPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('JPG·PNG·WebP 사진을 10MB 이하로 선택해 주세요.');const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('사진을 읽지 못했습니다.'));r.readAsDataURL(file);});const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('사진을 열지 못했습니다.'));img.src=url;});const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let quality=.85,data=canvas.toDataURL('image/jpeg',quality);while(data.length>530000&&quality>.3){quality-=.1;data=canvas.toDataURL('image/jpeg',quality);}if(data.length>530000)throw Error('사진 용량이 큽니다. 더 작은 사진을 선택해 주세요.');return {name:file.name.slice(0,200),data};}
document.addEventListener('change',async e=>{if(e.target.id!=='wiki-photo-input')return;const input=e.target,form=input.closest('form'),note=form.querySelector('.board-status'),button=form.querySelector('[type=submit]'),version=wikiUploadVersion,files=[...input.files];if(wikiUploadImages.length+files.length>3){note.textContent='사진은 최대 3장 첨부할 수 있습니다.';input.value='';return;}button.disabled=true;input.disabled=true;note.textContent='사진을 준비하는 중…';try{const images=[];for(const file of files)images.push(await compressWikiPhoto(file));if(version!==wikiUploadVersion)return;wikiUploadImages.push(...images);wikiPhotoPreview();note.textContent='사진이 준비되었습니다. 문서 등록을 누르면 함께 저장됩니다.';}catch(error){note.textContent=error.message;}finally{button.disabled=false;input.disabled=false;input.value='';}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-wiki-photo-remove]');if(!b)return;wikiUploadImages.splice(Number(b.dataset.wikiPhotoRemove),1);wikiPhotoPreview();});

let autoNewsArticles=[],autoNewsCategory='',autoNewsToday='';
function paintAutoNews(){const list=document.querySelector('#auto-news-list');if(!list)return;document.querySelector('#auto-news-filters').innerHTML=['','경제·금융','부동산'].map(c=>`<button type="button" data-news-category="${c}" aria-pressed="${autoNewsCategory===c}" class="${autoNewsCategory===c?'selected':''}">${c||'전체'}</button>`).join('');const articles=autoNewsArticles.filter(a=>!autoNewsCategory||a.category===autoNewsCategory);list.innerHTML=articles.length?articles.map(a=>`<a class="wiki-title-row auto-news-row" href="${esc(a.link)}" target="_blank" rel="noopener noreferrer"><span class="wiki-title-main"><strong>${esc(a.title)}</strong><small>매일경제 · ${esc(a.category)} · ${esc(a.published.slice(0,10))} ${esc(a.published.slice(11,16))}${a.published.slice(0,10)===autoNewsToday?' · 오늘':''}</small></span><span aria-hidden="true">↗</span></a>`).join(''):'<div class="meal-empty">현재 표시할 기사가 없습니다. 잠시 후 다시 확인해 주세요.</div>';}
async function loadAutoNews(){const list=document.querySelector('#auto-news-list');if(!list)return;try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);let data;try{const response=await fetch('/api/news',{credentials:'same-origin',signal:controller.signal});data=await response.json();if(!response.ok)throw Error(data.error||'기사 수집에 연결하지 못했습니다.');}finally{clearTimeout(timer);}if(!list.isConnected)return;autoNewsArticles=data.articles;autoNewsToday=data.today;paintAutoNews();document.querySelector('#auto-news-status').textContent=(data.updated?'마지막 수집: '+data.updated.slice(0,10)+' '+data.updated.slice(11,16)+' · 방문 시 최대 1시간 간격으로 자동 갱신':'수집을 준비하고 있습니다.')+(data.notice?' · '+data.notice:'');}catch(error){if(list.isConnected){list.innerHTML='<div class="meal-empty"><p></p><button type="button" class="primary" id="auto-news-retry">다시 불러오기</button></div>';list.querySelector('p').textContent=error.name==='AbortError'?'기사 연결이 지연되고 있습니다. 다시 시도해 주세요.':error.message;list.querySelector('button').onclick=()=>{list.textContent='기사를 불러오는 중…';loadAutoNews();};}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-news-category]');if(b){autoNewsCategory=b.dataset.newsCategory;paintAutoNews();}});
setInterval(()=>{if(location.hash==='#articles'&&!document.hidden)loadAutoNews();},60000);
